<?php
namespace App\Exports;
use App\Models\TransportService;use Maatwebsite\Excel\Concerns\{FromCollection,WithHeadings,WithMapping};
class TransportOperationExport implements FromCollection,WithHeadings,WithMapping { public function __construct(private int $company,private array $filters){} public function collection(){$q=TransportService::forCompany($this->company)->with(['vehicle','driver.employee','actualVehicle','actualDriver.employee','passengers','issues'])->orderBy('scheduled_start_at');if($this->filters['from']??null)$q->whereDate('service_date','>=',$this->filters['from']);if($this->filters['to']??null)$q->whereDate('service_date','<=',$this->filters['to']);return$q->get();} public function headings():array{return ['Fecha','Ruta','Salida programada','Salida real','Llegada programada','Llegada real','Vehículo programado','Vehículo real','Conductor programado','Conductor real','Pasajeros esperados','Pasajeros transportados','Novedades','Estado'];} public function map($s):array{return [$s->service_date->format('d/m/Y'),$s->route_name_snapshot,$s->scheduled_start_at->format('d/m/Y H:i'),$s->actual_start_at?->format('d/m/Y H:i'),$s->scheduled_arrival_at->format('d/m/Y H:i'),$s->actual_arrival_at?->format('d/m/Y H:i'),$s->vehicle?->plate,$s->actualVehicle?->plate,$s->driver?->display_name,$s->actualDriver?->display_name,$s->expected_passenger_count,$s->actual_passenger_count,$s->issues->count(),config('transport.service_statuses.'.$s->status,$s->status)];} }
